SELECT c.class_id,c.school_year,c.grade_code,c.class_code,c.class_name,CONVERT(char(10),c.valid_from,23),CONVERT(char(10),c.valid_to,23),c.is_active,c.capacity,g.code_name,(SELECT COUNT_BIG(*) FROM dbo.m_student s WHERE s.class_id=c.class_id AND s.is_deleted=0 AND s.enrollment_status_code IN ('01','02')) FROM dbo.m_class c LEFT JOIN dbo.m_code g ON g.category_id=c.grade_category AND g.code_value=c.grade_code ORDER BY school_year DESC,g.display_order,c.display_order,class_code,class_id;
